// Detect oversharing in site permissions and drives
const siteData = $node['Loop Sites'].json;
const permissions = $input.item(0).json.permissions?.value || [];
const drives = $input.item(1).json.value || [];
const overshared = [];

// Check site-level permissions
for (const perm of permissions) {
  // Anonymous link detection
  if (perm.link?.scope === 'anonymous') {
    overshared.push({
      type: 'ANONYMOUS_LINK',
      severity: 'HIGH',
      resourceType: 'site',
      resourceName: siteData.displayName || siteData.name,
      resourceId: siteData.id,
      linkUrl: perm.link.webUrl,
      linkType: perm.link.type,
      timestamp: new Date().toISOString()
    });
  }

  // External sharing detection
  if (perm.grantedToV2?.user?.email && perm.grantedToV2.user.email.includes('@external')) {
    overshared.push({
      type: 'EXTERNAL_SHARING',
      severity: 'MEDIUM',
      resourceType: 'site',
      resourceName: siteData.displayName || siteData.name,
      resourceId: siteData.id,
      sharedWith: perm.grantedToV2.user.email,
      roles: perm.roles || [],
      timestamp: new Date().toISOString()
    });
  }

  // Everyone/organization-wide sharing
  if (perm.grantedToIdentitiesV2?.some(id => id.user?.displayName === 'Everyone')) {
    overshared.push({
      type: 'EVERYONE_SHARING',
      severity: 'HIGH',
      resourceType: 'site',
      resourceName: siteData.displayName || siteData.name,
      resourceId: siteData.id,
      roles: perm.roles || [],
      timestamp: new Date().toISOString()
    });
  }
}

// Check drive-level sharing
for (const drive of drives) {
  if (drive.sharingCapabilities?.external === 'enabled') {
    overshared.push({
      type: 'DRIVE_EXTERNAL_SHARING_ENABLED',
      severity: 'MEDIUM',
      resourceType: 'drive',
      resourceName: `${siteData.displayName} - ${drive.name}`,
      resourceId: drive.id,
      siteId: siteData.id,
      timestamp: new Date().toISOString()
    });
  }
}

return overshared.map(o => ({json: o}));

// Aggregate all oversharing detections
const allDetections = $input.all().map(item => item.json);

if (allDetections.length === 0) {
  return [{
    json: {
      channel: '#security-alerts',
      text: '✅ No oversharing detected in daily scan',
      hasIssues: false
    }
  }];
}

// Group by severity and type
const bySeverity = {
  HIGH: allDetections.filter(d => d.severity === 'HIGH'),
  MEDIUM: allDetections.filter(d => d.severity === 'MEDIUM'),
  LOW: allDetections.filter(d => d.severity === 'LOW')
};

const byType = {};
for (const detection of allDetections) {
  byType[detection.type] = (byType[detection.type] || 0) + 1;
}

let message = `🔓 *Oversharing Detection Report*\n\n`;
message += `Total Issues: ${allDetections.length}\n`;
message += `• High Severity: ${bySeverity.HIGH.length}\n`;
message += `• Medium Severity: ${bySeverity.MEDIUM.length}\n`;
message += `• Low Severity: ${bySeverity.LOW.length}\n\n`;

message += `*Issue Types*\n`;
for (const [type, count] of Object.entries(byType)) {
  message += `• ${type.replace(/_/g, ' ')}: ${count}\n`;
}
message += `\n`;

// Show top HIGH severity issues
if (bySeverity.HIGH.length > 0) {
  message += `⚠️ *Critical Issues*\n`;
  bySeverity.HIGH.slice(0, 5).forEach(issue => {
    message += `• ${issue.resourceName}: ${issue.type}\n`;
    if (issue.linkUrl) message += `  Link: ${issue.linkUrl}\n`;
    if (issue.sharedWith) message += `  Shared with: ${issue.sharedWith}\n`;
  });
  if (bySeverity.HIGH.length > 5) {
    message += `... and ${bySeverity.HIGH.length - 5} more\n`;
  }
}

message += `\nTimestamp: ${new Date().toISOString()}`;

return [{
  json: {
    channel: '#security-alerts',
    text: message,
    hasIssues: true,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: '🔓 Oversharing Alert',
          emoji: true
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: message
        }
      }
    ]
  }
}];
